package com.vor506.groundlootmenu;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup("groundlootmenu")
public interface GroundLootMenuConfig extends Config
{
	@ConfigItem(
		keyName = "hideLowValue",
		name = "Hide low-value items",
		description = "Hide ground-item stacks below the minimum total GE value.",
		position = 0
	)
	default boolean hideLowValue()
	{
		return true;
	}

	@Range(min = 0, max = 2147483647)
	@ConfigItem(
		keyName = "minimumTotalGeValue",
		name = "Minimum total GE value",
		description = "Minimum GE value of the entire stack, in GP.",
		position = 1
	)
	default int minimumTotalGeValue()
	{
		return 100;
	}

	@ConfigItem(
		keyName = "hideUnpriced",
		name = "Hide unpriced items",
		description = "Hide items with no positive GE price.",
		position = 2
	)
	default boolean hideUnpriced()
	{
		return false;
	}

	@ConfigItem(
		keyName = "ignoreList",
		name = "Ignore list",
		description = "Comma-separated item names to hide, unless listed as valuable.",
		position = 3
	)
	default String ignoreList()
	{
		return "";
	}

	@ConfigItem(
		keyName = "valuableItems",
		name = "Always show items",
		description = "Comma-separated item names that bypass the ignore, minimum-value, and unpriced filters.",
		position = 5
	)
	default String valuableItems()
	{
		return "";
	}

	@ConfigItem(
		keyName = "sortOrder",
		name = "Sort order",
		description = "Choose value, quantity, or name.",
		position = 6
	)
	default SortOrder sortOrder()
	{
		return SortOrder.VALUE;
	}

	enum SortOrder
	{
		VALUE,
		QUANTITY,
		NAME
	}

	@ConfigItem(
		keyName = "showQuantity",
		name = "Show quantity",
		description = "Display stack quantity on each item icon.",
		position = 7
	)
	default boolean showQuantity()
	{
		return true;
	}

	@ConfigItem(
		keyName = "autoCollapse",
		name = "Auto-collapse when empty",
		description = "Collapse the panel when no items pass the filters.",
		position = 8
	)
	default boolean autoCollapse()
	{
		return true;
	}

	@ConfigItem(
		keyName = "autoExpand",
		name = "Open panel when loot appears",
		description = "Expand the panel when eligible loot appears. Turn this off to leave the panel closed after you collapse it.",
		position = 9
	)
	default boolean autoExpand()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showGeTotal",
		name = "Show GE total",
		description = "Display the total Grand Exchange value.",
		position = 10
	)
	default boolean showGeTotal()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showHighAlchTotal",
		name = "Show high-alch total",
		description = "Display the total high-alchemy value.",
		position = 11
	)
	default boolean showHighAlchTotal()
	{
		return true;
	}

	@Range(min = 0, max = 300)
	@Units(Units.SECONDS)
	@ConfigItem(
		keyName = "highlightSeconds",
		name = "Clear highlight after",
		description = "Seconds before a selected tile is unmarked. Set to 0 to keep the mark until you click that item again.",
		position = 12
	)
	default int highlightSeconds()
	{
		return 0;
	}

	@ConfigItem(
		keyName = "highlightOnHover",
		name = "Highlight tile on hover",
		description = "Show a tile highlight while the cursor is over a slot. It clears when the cursor leaves, and does not change the left-click.",
		position = 13
	)
	default boolean highlightOnHover()
	{
		return true;
	}
}

package com.vor506.groundlootmenu;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Stroke;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

public class GroundLootMenuOverlay extends Overlay
{
	static final int VISIBLE_SLOTS = 16;

	private static final int COLUMNS = 4;
	private static final int ROWS = 4;
	private static final int SLOT_WIDTH = 48;
	private static final int SLOT_HEIGHT = 52;
	private static final int GAP = 3;
	private static final int GRID_X = 8;
	private static final int GRID_Y = 40;
	private static final int WIDTH = 217;
	private static final int HEIGHT = 298;
	private static final int COLLAPSED_WIDTH = 48;
	private static final int COLLAPSED_HEIGHT = 40;

	private static final Font TITLE_FONT = new Font("SansSerif", Font.BOLD, 13);
	private static final Font COUNT_FONT = new Font("SansSerif", Font.PLAIN, 10);
	private static final Font TOTAL_FONT = new Font("SansSerif", Font.BOLD, 10);
	private static final Font QUANTITY_FONT = new Font("SansSerif", Font.BOLD, 10);
	private static final Font VALUE_FONT = new Font("SansSerif", Font.BOLD, 9);
	private static final Stroke SELECTED_STROKE = new BasicStroke(2.5f);
	private static final Stroke HOVER_STROKE = new BasicStroke(1.5f);

	private static final Color BACKGROUND = new Color(22, 19, 16, 245);
	private static final Color SLOT_BACKGROUND = new Color(34, 30, 25, 238);
	private static final Color SLOT_BORDER = new Color(71, 59, 43);
	private static final Color GOLD = new Color(177, 145, 83);
	private static final Color QUANTITY_COLOR = new Color(245, 238, 220);
	private static final Color VALUE_COLOR = new Color(166, 202, 137);
	private static final Color BADGE_BACKGROUND = new Color(20, 16, 12, 220);
	private static final Color COLLAPSE_FILL = new Color(65, 52, 36);
	private static final Color SATCHEL_OUTLINE = new Color(12, 8, 7);
	private static final Color SATCHEL_BODY = new Color(105, 20, 25);
	private static final Color SATCHEL_FLAP = new Color(145, 30, 35);
	private static final Color SATCHEL_HIGHLIGHT = new Color(181, 45, 45);
	private static final Color SATCHEL_SHADE = new Color(68, 13, 19);
	private static final Color CLASP_SHADE = new Color(48, 30, 12);
	private static final Color CLASP_GOLD = new Color(184, 133, 42);
	private static final Color CLASP_BRIGHT = new Color(244, 205, 92);
	private static final Color CHEVRON_SHADOW = new Color(10, 8, 6);
	private static final Color CHEVRON = new Color(220, 180, 83);

	private final ItemManager itemManager;
	private final GroundLootMenuConfig config;
	private final TooltipManager tooltipManager;
	private List<LootEntry> entries = Collections.emptyList();
	private LootEntry selectedEntry;
	private String itemCountText = "0 items";
	private String geTotalText = "G.E Value: 0";
	private String highAlchTotalText = "High alch value: 0";
	private boolean collapsed;
	private volatile int hoverX = -1;
	private volatile int hoverY = -1;

	@Inject
	public GroundLootMenuOverlay(ItemManager itemManager, GroundLootMenuConfig config, TooltipManager tooltipManager)
	{
		this.itemManager = itemManager;
		this.config = config;
		this.tooltipManager = tooltipManager;
		setPosition(OverlayPosition.DETACHED);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPreferredLocation(new Point(30, 120));
	}

	void showLoot(
		List<LootEntry> entries,
		int matchCount,
		String geTotal,
		String highAlchTotal,
		LootEntry selectedEntry)
	{
		this.entries = entries;
		this.selectedEntry = selectedEntry;
		this.itemCountText = matchCount + " items";
		this.geTotalText = "G.E Value: " + geTotal;
		this.highAlchTotalText = "High alch value: " + highAlchTotal;
	}

	void setSelectedEntry(LootEntry selectedEntry)
	{
		this.selectedEntry = selectedEntry;
	}

	void reset()
	{
		collapsed = false;
		hoverX = -1;
		hoverY = -1;
		showLoot(Collections.emptyList(), 0, "0", "0", null);
	}

	void setHover(int x, int y)
	{
		hoverX = x;
		hoverY = y;
	}

	LootEntry getHoveredEntry()
	{
		int x = hoverX;
		int y = hoverY;
		if (x < 0 || y < 0)
		{
			return null;
		}

		return getEntryAt(x, y);
	}

	public boolean isCollapsed()
	{
		return collapsed;
	}

	public void toggleCollapsed()
	{
		collapsed = !collapsed;
	}

	public boolean isCollapseButtonAt(int x, int y)
	{
		if (collapsed)
		{
			return x >= 0 && x < COLLAPSED_WIDTH
				&& y >= 0 && y < COLLAPSED_HEIGHT;
		}

		return x >= WIDTH - 28 && x <= WIDTH - 8
			&& y >= 5 && y <= 25;
	}

	public LootEntry getEntryAt(int x, int y)
	{
		if (collapsed || x < GRID_X || y < GRID_Y)
		{
			return null;
		}

		int relativeX = x - GRID_X;
		int relativeY = y - GRID_Y;
		int cellWidth = SLOT_WIDTH + GAP;
		int cellHeight = SLOT_HEIGHT + GAP;
		int column = relativeX / cellWidth;
		int row = relativeY / cellHeight;

		if (column < 0 || column >= COLUMNS || row < 0 || row >= ROWS)
		{
			return null;
		}

		if (relativeX % cellWidth >= SLOT_WIDTH
			|| relativeY % cellHeight >= SLOT_HEIGHT)
		{
			return null;
		}

		int index = row * COLUMNS + column;
		if (index >= entries.size())
		{
			return null;
		}

		return entries.get(index);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (collapsed)
		{
			renderCollapsed(graphics);
			return new Dimension(COLLAPSED_WIDTH, COLLAPSED_HEIGHT);
		}

		graphics.setColor(BACKGROUND);
		graphics.fillRoundRect(0, 0, WIDTH, HEIGHT, 8, 8);

		graphics.setColor(GOLD);
		graphics.drawRoundRect(0, 0, WIDTH - 1, HEIGHT - 1, 8, 8);

		graphics.setFont(TITLE_FONT);
		graphics.drawString("Ground Loot", 10, 19);

		graphics.setFont(COUNT_FONT);
		graphics.setColor(Color.LIGHT_GRAY);
		graphics.drawString(itemCountText, 10, 29);

		renderCollapseButton(graphics);

		for (int index = 0; index < VISIBLE_SLOTS; index++)
		{
			int column = index % COLUMNS;
			int row = index / COLUMNS;
			int x = GRID_X + column * (SLOT_WIDTH + GAP);
			int y = GRID_Y + row * (SLOT_HEIGHT + GAP);
			renderSlot(graphics, x, y, index);
		}

		renderTotals(graphics);
		renderTooltip();
		return new Dimension(WIDTH, HEIGHT);
	}

	private void renderTooltip()
	{
		int x = hoverX;
		int y = hoverY;
		if (x < 0 || y < 0)
		{
			return;
		}

		LootEntry entry = getHoveredEntry();
		if (entry == null)
		{
			return;
		}

		tooltipManager.add(new Tooltip(entry.getName()));
	}

	private void renderTotals(Graphics2D graphics)
	{
		boolean showGeTotal = config.showGeTotal();
		boolean showHighAlchTotal = config.showHighAlchTotal();
		if (!showGeTotal && !showHighAlchTotal)
		{
			return;
		}

		int gridBottom = GRID_Y + ROWS * SLOT_HEIGHT + (ROWS - 1) * GAP;
		int dividerY = gridBottom + 4;

		graphics.setColor(SLOT_BORDER);
		graphics.drawLine(8, dividerY, WIDTH - 8, dividerY);
		graphics.setFont(TOTAL_FONT);
		graphics.setColor(GOLD);

		int lineY = dividerY + 14;
		if (showGeTotal)
		{
			graphics.drawString(geTotalText, 10, lineY);
			lineY += 14;
		}

		if (showHighAlchTotal)
		{
			graphics.drawString(highAlchTotalText, 10, lineY);
		}
	}

	private void renderCollapsed(Graphics2D graphics)
	{
		graphics.setColor(BACKGROUND);
		graphics.fillRoundRect(0, 0, COLLAPSED_WIDTH, COLLAPSED_HEIGHT, 6, 6);
		graphics.setColor(GOLD);
		graphics.drawRoundRect(0, 0, COLLAPSED_WIDTH - 1, COLLAPSED_HEIGHT - 1, 6, 6);

		graphics.setColor(SATCHEL_OUTLINE);
		graphics.fillRect(9, 4, 17, 4);
		graphics.fillRect(6, 8, 25, 6);
		graphics.fillRect(4, 14, 29, 14);
		graphics.fillRect(7, 28, 24, 4);
		graphics.fillRect(11, 32, 17, 3);
		graphics.fillRect(31, 17, 2, 9);

		graphics.setColor(SATCHEL_BODY);
		graphics.fillRect(8, 11, 22, 17);
		graphics.fillRect(6, 15, 25, 12);
		graphics.fillRect(10, 28, 19, 4);

		graphics.setColor(SATCHEL_FLAP);
		graphics.fillRect(10, 9, 18, 6);
		graphics.fillRect(8, 15, 5, 11);
		graphics.fillRect(13, 16, 15, 10);
		graphics.fillRect(13, 27, 12, 3);

		graphics.setColor(SATCHEL_HIGHLIGHT);
		graphics.fillRect(11, 10, 13, 3);
		graphics.fillRect(9, 16, 3, 7);
		graphics.fillRect(14, 19, 10, 4);

		graphics.setColor(SATCHEL_SHADE);
		graphics.fillRect(28, 15, 3, 12);
		graphics.fillRect(25, 27, 4, 4);
		graphics.fillRect(24, 31, 4, 1);

		graphics.setColor(CLASP_SHADE);
		graphics.fillRect(16, 14, 7, 13);
		graphics.setColor(CLASP_GOLD);
		graphics.fillRect(17, 15, 5, 11);
		graphics.setColor(CLASP_BRIGHT);
		graphics.fillRect(18, 17, 3, 7);
		graphics.fillRect(18, 14, 4, 2);

		graphics.setColor(CHEVRON_SHADOW);
		graphics.drawLine(37, 18, 41, 21);
		graphics.drawLine(41, 21, 37, 24);
		graphics.setColor(CHEVRON);
		graphics.drawLine(37, 17, 40, 20);
		graphics.drawLine(40, 20, 37, 23);
	}

	private void renderCollapseButton(Graphics2D graphics)
	{
		graphics.setColor(COLLAPSE_FILL);
		graphics.fillRoundRect(WIDTH - 28, 5, 20, 20, 4, 4);
		graphics.setColor(GOLD);
		graphics.drawRoundRect(WIDTH - 28, 5, 20, 20, 4, 4);
		graphics.drawLine(WIDTH - 23, 15, WIDTH - 13, 15);
	}

	private void renderSlot(Graphics2D graphics, int x, int y, int index)
	{
		graphics.setColor(SLOT_BACKGROUND);
		graphics.fillRoundRect(x, y, SLOT_WIDTH, SLOT_HEIGHT, 5, 5);
		graphics.setColor(SLOT_BORDER);
		graphics.drawRoundRect(x, y, SLOT_WIDTH - 1, SLOT_HEIGHT - 1, 5, 5);

		if (index >= entries.size())
		{
			return;
		}

		LootEntry entry = entries.get(index);
		if (entry.samePileItem(selectedEntry))
		{
			double pulse = 0.5 + 0.5 * Math.sin(System.currentTimeMillis() / 140.0);
			Stroke previousStroke = graphics.getStroke();
			graphics.setColor(new Color(255, 190, 40, 35 + (int) (75 * pulse)));
			graphics.fillRoundRect(x, y, SLOT_WIDTH, SLOT_HEIGHT, 5, 5);
			graphics.setColor(new Color(255, 225, 135, 115 + (int) (140 * pulse)));
			graphics.setStroke(SELECTED_STROKE);
			graphics.drawRoundRect(x + 1, y + 1, SLOT_WIDTH - 2, SLOT_HEIGHT - 2, 5, 5);
			graphics.setStroke(previousStroke);
		}
		else if (config.highlightOnHover() && entry.samePileItem(getHoveredEntry()))
		{
			Stroke previousStroke = graphics.getStroke();
			graphics.setColor(new Color(255, 225, 135, 170));
			graphics.setStroke(HOVER_STROKE);
			graphics.drawRoundRect(x + 1, y + 1, SLOT_WIDTH - 2, SLOT_HEIGHT - 2, 5, 5);
			graphics.setStroke(previousStroke);
		}

		graphics.drawImage(
			itemManager.getImage(entry.getItemId(), entry.getQuantity(), entry.isStackable()),
			x + 8,
			y + 5,
			32,
			32,
			null);

		if (config.showQuantity() && entry.getQuantity() > 1)
		{
			String quantity = entry.getQuantityText();
			graphics.setFont(QUANTITY_FONT);
			int badgeWidth = graphics.getFontMetrics().stringWidth(quantity) + 6;
			int badgeX = x + SLOT_WIDTH - badgeWidth - 3;
			int badgeY = y + 3;

			graphics.setColor(BADGE_BACKGROUND);
			graphics.fillRoundRect(badgeX, badgeY, badgeWidth, 13, 4, 4);
			graphics.setColor(QUANTITY_COLOR);
			graphics.drawString(quantity, badgeX + 3, badgeY + 10);
		}

		graphics.setFont(VALUE_FONT);
		graphics.setColor(VALUE_COLOR);
		String value = entry.getValueText();
		int textWidth = graphics.getFontMetrics().stringWidth(value);
		graphics.drawString(
			value,
			x + Math.max(2, (SLOT_WIDTH - textWidth) / 2),
			y + SLOT_HEIGHT - 6);
	}
}

package com.vor506.groundlootmenu;

import com.google.inject.Provides;
import java.awt.Component;
import java.awt.Container;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.Window;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JPopupMenu;
import javax.swing.SwingUtilities;
import javax.swing.text.JTextComponent;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Player;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
		name = "Ground Loot Menu",
		description = "Shows nearby ground items and highlights the selected pile"
)
public class GroundLootMenuPlugin extends Plugin
{
	private static final String CONFIG_GROUP = "groundlootmenu";
	private static final int RANGE = 15;
	private static final Pattern COLOR_TAG = Pattern.compile("(?i)</?col(?:=[^>]*)?>");
	private static final Comparator<LootEntry> BY_VALUE = Comparator
			.comparingLong(LootEntry::getTotalValue)
			.reversed()
			.thenComparing(LootEntry::getName);
	private static final Comparator<LootEntry> BY_QUANTITY = Comparator
			.comparingInt(LootEntry::getQuantity)
			.reversed()
			.thenComparing(LootEntry::getName);
	private static final Comparator<LootEntry> BY_NAME = Comparator
			.comparing(LootEntry::getName, String.CASE_INSENSITIVE_ORDER);

	@Inject
	private Client client;

	@Inject
	private ItemManager itemManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private MouseManager mouseManager;

	@Inject
	private GroundLootMenuOverlay overlay;

	@Inject
	private GroundLootTargetOverlay targetOverlay;

	@Inject
	private GroundLootMenuConfig config;

	@Inject
	private ConfigManager configManager;

	private volatile LootEntry selectedEntry;
	private long selectedAtMillis;
	private boolean dragging;
	private boolean hadEligibleLoot;
	private Point dragOffset;
	private JPopupMenu activeMenu;
	private String cachedIgnoreList;
	private String cachedValuableList;
	private Set<String> ignoredNames = Collections.emptySet();
	private Set<String> valuableNames = Collections.emptySet();

	private final MouseAdapter mouseAdapter = new MouseAdapter()
	{
		@Override
		public MouseEvent mousePressed(MouseEvent event)
		{
			Rectangle bounds = overlay.getBounds();

			if (bounds == null || !bounds.contains(event.getPoint()))
			{
				return event;
			}

			if (SwingUtilities.isLeftMouseButton(event) && event.isAltDown())
			{
				dragging = true;
				dragOffset = new Point(
						event.getX() - bounds.x,
						event.getY() - bounds.y);
				event.consume();
				return event;
			}

			if (SwingUtilities.isRightMouseButton(event))
			{
				int x = event.getX() - bounds.x;
				int y = event.getY() - bounds.y;
				LootEntry entry = overlay.isCollapsed() ? null : overlay.getEntryAt(x, y);

				if (entry != null)
				{
					showQuickAddMenu(event, entry);
				}

				event.consume();
				return event;
			}

			if (SwingUtilities.isLeftMouseButton(event))
			{
				int x = event.getX() - bounds.x;
				int y = event.getY() - bounds.y;

				if (overlay.isCollapseButtonAt(x, y) || overlay.isCollapsed())
				{
					overlay.toggleCollapsed();
				}
				else
				{
					LootEntry entry = overlay.getEntryAt(x, y);
					if (entry != null)
					{
						selectEntry(entry);
					}
				}
			}

			event.consume();
			return event;
		}

		@Override
		public MouseEvent mouseMoved(MouseEvent event)
		{
			updateHover(event);
			return event;
		}

		@Override
		public MouseEvent mouseDragged(MouseEvent event)
		{
			updateHover(event);

			if (dragging && dragOffset != null)
			{
				overlay.setPreferredLocation(new Point(
						event.getX() - dragOffset.x,
						event.getY() - dragOffset.y));
				event.consume();
			}

			return event;
		}

		@Override
		public MouseEvent mouseExited(MouseEvent event)
		{
			overlay.setHover(-1, -1);
			return event;
		}

		@Override
		public MouseEvent mouseReleased(MouseEvent event)
		{
			if (dragging)
			{
				dragging = false;
				dragOffset = null;
				event.consume();
			}

			return event;
		}
	};

	@Provides
	GroundLootMenuConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GroundLootMenuConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		overlayManager.add(targetOverlay);
		mouseManager.registerMouseListener(mouseAdapter);
	}

	@Override
	protected void shutDown()
	{
		mouseManager.unregisterMouseListener(mouseAdapter);
		overlayManager.remove(overlay);
		overlayManager.remove(targetOverlay);
		hideQuickAddMenu();
		selectedEntry = null;
		selectedAtMillis = 0L;
		hadEligibleLoot = false;
		dragging = false;
		dragOffset = null;
		cachedIgnoreList = null;
		cachedValuableList = null;
		ignoredNames = Collections.emptySet();
		valuableNames = Collections.emptySet();
		overlay.reset();
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		expireSelection();
		LootEntry selected = selectedEntry;
		if (selected == null)
		{
			return;
		}

		MenuAction type = MenuAction.of(event.getType());
		if (type == null || !isPileOption(type))
		{
			return;
		}

		if (event.getActionParam0() != selected.getSceneX()
				|| event.getActionParam1() != selected.getSceneY())
		{
			return;
		}

		MenuEntry menuEntry = event.getMenuEntry();
		if (menuEntry == null)
		{
			return;
		}

		if (event.getIdentifier() != selected.getItemId())
		{
			menuEntry.setDeprioritized(true);
			return;
		}

		String target = menuEntry.getTarget();
		if (target == null || target.isEmpty())
		{
			return;
		}

		menuEntry.setTarget("<col=FFD700>" + COLOR_TAG.matcher(target).replaceAll("") + "</col>");
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		Player player = client.getLocalPlayer();
		Scene scene = client.getScene();
		LocalPoint local = player == null ? null : player.getLocalLocation();

		if (player == null || scene == null || local == null)
		{
			clearLoot(true);
			return;
		}

		Tile[][][] tiles = scene.getTiles();
		int plane = client.getPlane();
		if (plane < 0 || plane >= tiles.length || tiles[plane] == null)
		{
			clearLoot(true);
			return;
		}

		refreshNameLists();
		long[] totals = new long[2];
		List<LootEntry> found = collectLoot(player.getWorldLocation(), local, tiles[plane], totals);
		sortLoot(found);
		expireSelection();
		updateSelectedEntry(found);

		int visibleCount = Math.min(GroundLootMenuOverlay.VISIBLE_SLOTS, found.size());
		List<LootEntry> visible = visibleCount == found.size()
				? found
				: new ArrayList<>(found.subList(0, visibleCount));
		overlay.showLoot(
				visible,
				found.size(),
				LootEntry.formatAmount(totals[0]),
				LootEntry.formatAmount(totals[1]),
				selectedEntry);

		boolean hasEligibleLoot = !found.isEmpty();
		if (hasEligibleLoot != hadEligibleLoot)
		{
			boolean expand = hasEligibleLoot && config.autoExpand() && overlay.isCollapsed();
			boolean collapse = !hasEligibleLoot && config.autoCollapse() && !overlay.isCollapsed();
			if (expand || collapse)
			{
				overlay.toggleCollapsed();
			}
		}

		hadEligibleLoot = hasEligibleLoot;
	}

	LootEntry getSelectedEntry()
	{
		expireSelection();
		return selectedEntry;
	}

	LootEntry getHoveredEntry()
	{
		if (!config.highlightOnHover())
		{
			return null;
		}

		return overlay.getHoveredEntry();
	}

	private void updateHover(MouseEvent event)
	{
		Rectangle bounds = overlay.getBounds();
		if (bounds == null || !bounds.contains(event.getPoint()))
		{
			overlay.setHover(-1, -1);
			return;
		}

		overlay.setHover(event.getX() - bounds.x, event.getY() - bounds.y);
	}

	private void selectEntry(LootEntry entry)
	{
		if (entry.samePileItem(selectedEntry))
		{
			clearSelection();
			return;
		}

		selectedEntry = entry;
		selectedAtMillis = System.currentTimeMillis();
		overlay.setSelectedEntry(entry);
	}

	private void clearSelection()
	{
		selectedEntry = null;
		selectedAtMillis = 0L;
		overlay.setSelectedEntry(null);
	}

	private void expireSelection()
	{
		if (selectedEntry == null)
		{
			return;
		}

		int seconds = config.highlightSeconds();
		if (seconds <= 0)
		{
			return;
		}

		if (System.currentTimeMillis() - selectedAtMillis >= seconds * 1000L)
		{
			clearSelection();
		}
	}

	private void clearLoot(boolean collapseWhenEmpty)
	{
		selectedEntry = null;
		selectedAtMillis = 0L;
		overlay.showLoot(Collections.emptyList(), 0, "0", "0", null);
		if (collapseWhenEmpty && config.autoCollapse() && !overlay.isCollapsed())
		{
			overlay.toggleCollapsed();
		}
		hadEligibleLoot = false;
	}

	private List<LootEntry> collectLoot(WorldPoint playerLocation, LocalPoint local, Tile[][] planeTiles, long[] totals)
	{
		int minX = Math.max(0, local.getSceneX() - RANGE);
		int maxX = Math.min(planeTiles.length - 1, local.getSceneX() + RANGE);
		List<LootEntry> found = new ArrayList<>();

		for (int x = minX; x <= maxX; x++)
		{
			Tile[] column = planeTiles[x];
			if (column == null)
			{
				continue;
			}

			int minY = Math.max(0, local.getSceneY() - RANGE);
			int maxY = Math.min(column.length - 1, local.getSceneY() + RANGE);
			for (int y = minY; y <= maxY; y++)
			{
				collectTile(column[y], playerLocation, found, totals);
			}
		}

		return found;
	}

	private void collectTile(Tile tile, WorldPoint playerLocation, List<LootEntry> found, long[] totals)
	{
		if (tile == null || tile.getGroundItems() == null)
		{
			return;
		}

		WorldPoint location = tile.getWorldLocation();
		LocalPoint localLocation = tile.getLocalLocation();
		if (location == null || localLocation == null
				|| playerLocation.distanceTo(location) > RANGE)
		{
			return;
		}

		for (TileItem item : tile.getGroundItems())
		{
			LootEntry entry = toEntry(item, location, localLocation);
			if (entry != null)
			{
				found.add(entry);
				totals[0] += entry.getTotalValue();
				totals[1] += entry.getHighAlchValue();
			}
		}
	}

	private LootEntry toEntry(TileItem item, WorldPoint location, LocalPoint localLocation)
	{
		if (item.getOwnership() == TileItem.OWNERSHIP_OTHER || item.getQuantity() <= 0)
		{
			return null;
		}

		int id = item.getId();
		ItemComposition composition = itemManager.getItemComposition(id);
		String name = composition.getName();
		if (name == null || name.isEmpty())
		{
			return null;
		}

		int quantity = item.getQuantity();
		String normalizedName = name.trim().toLowerCase(Locale.ROOT);
		long unitPrice = itemManager.getItemPrice(id);
		if (!valuableNames.contains(normalizedName))
		{
			if (ignoredNames.contains(normalizedName))
			{
				return null;
			}

			if (config.hideUnpriced() && unitPrice <= 0)
			{
				return null;
			}

			if (config.hideLowValue() && unitPrice * (long) quantity < config.minimumTotalGeValue())
			{
				return null;
			}
		}

		return new LootEntry(
				id,
				quantity,
				name,
				location,
				localLocation.getSceneX(),
				localLocation.getSceneY(),
				unitPrice * (long) quantity,
				(long) composition.getHaPrice() * quantity,
				composition.isStackable());
	}

	private void sortLoot(List<LootEntry> found)
	{
		switch (config.sortOrder())
		{
			case QUANTITY:
				found.sort(BY_QUANTITY);
				break;
			case NAME:
				found.sort(BY_NAME);
				break;
			default:
				found.sort(BY_VALUE);
				break;
		}
	}

	private void updateSelectedEntry(List<LootEntry> found)
	{
		LootEntry selected = selectedEntry;
		if (selected == null)
		{
			return;
		}

		for (LootEntry entry : found)
		{
			if (entry.samePileItem(selected))
			{
				selectedEntry = entry;
				return;
			}
		}

		selectedEntry = null;
	}

	private void refreshNameLists()
	{
		String ignoreList = config.ignoreList() == null ? "" : config.ignoreList();
		if (!ignoreList.equals(cachedIgnoreList))
		{
			cachedIgnoreList = ignoreList;
			ignoredNames = parseItemNames(ignoreList);
		}

		String valuableList = config.valuableItems() == null ? "" : config.valuableItems();
		if (!valuableList.equals(cachedValuableList))
		{
			cachedValuableList = valuableList;
			valuableNames = parseItemNames(valuableList);
		}
	}

	private static Set<String> parseItemNames(String input)
	{
		if (input == null || input.trim().isEmpty())
		{
			return Collections.emptySet();
		}

		Set<String> names = new HashSet<>();
		for (String part : input.split("[,\\r\\n]+"))
		{
			String normalized = part.trim().toLowerCase(Locale.ROOT);
			if (!normalized.isEmpty())
			{
				names.add(normalized);
			}
		}

		return names;
	}

	private static boolean isPileOption(MenuAction type)
	{
		switch (type)
		{
			case GROUND_ITEM_FIRST_OPTION:
			case GROUND_ITEM_SECOND_OPTION:
			case GROUND_ITEM_THIRD_OPTION:
			case GROUND_ITEM_FOURTH_OPTION:
			case GROUND_ITEM_FIFTH_OPTION:
			case EXAMINE_ITEM_GROUND:
				return true;
			default:
				return false;
		}
	}

	private void showQuickAddMenu(MouseEvent event, LootEntry entry)
	{
		String itemName = entry.getName();
		java.awt.Component component = event.getComponent();
		int x = event.getX();
		int y = event.getY();

		SwingUtilities.invokeLater(() ->
		{
			hideQuickAddMenu();
			JPopupMenu menu = new JPopupMenu();
			addListMenuItem(menu, "ignoreList", "Ignore", itemName);
			addListMenuItem(menu, "valuableItems", "Always show", itemName);
			activeMenu = menu;
			menu.show(component, x, y);
		});
	}

	private void hideQuickAddMenu()
	{
		if (SwingUtilities.isEventDispatchThread())
		{
			dismissQuickAddMenu();
		}
		else
		{
			SwingUtilities.invokeLater(this::dismissQuickAddMenu);
		}
	}

	private void dismissQuickAddMenu()
	{
		JPopupMenu menu = activeMenu;
		activeMenu = null;
		if (menu != null)
		{
			menu.setVisible(false);
		}
	}

	private void addListMenuItem(JPopupMenu menu, String key, String label, String itemName)
	{
		boolean alreadyListed = parseItemNames(listValue(key))
				.contains(itemName.trim().toLowerCase(Locale.ROOT));
		JMenuItem item = new JMenuItem((alreadyListed ? "Remove from " : "Add to ") + label);
		item.addActionListener(e -> updateItemList(key, itemName, !alreadyListed));
		menu.add(item);
	}

	private void updateItemList(String key, String itemName, boolean add)
	{
		List<String> names = new ArrayList<>();
		String currentValue = listValue(key);

		if (!currentValue.trim().isEmpty())
		{
			for (String part : currentValue.split("[,\\r\\n]+"))
			{
				String trimmed = part.trim();
				if (!trimmed.isEmpty())
				{
					names.add(trimmed);
				}
			}
		}

		String normalizedName = itemName.trim().toLowerCase(Locale.ROOT);
		boolean exists = names.stream().anyMatch(name ->
				name.toLowerCase(Locale.ROOT).equals(normalizedName));

		if (add && !exists)
		{
			names.add(itemName.trim());
		}
		else if (!add)
		{
			names.removeIf(name -> name.toLowerCase(Locale.ROOT).equals(normalizedName));
		}
		else
		{
			return;
		}

		String updated = String.join(", ", names);
		if (updated.isEmpty())
		{
			configManager.unsetConfiguration(CONFIG_GROUP, key);
		}
		else
		{
			configManager.setConfiguration(CONFIG_GROUP, key, updated);
		}

		if ("ignoreList".equals(key))
		{
			cachedIgnoreList = updated;
			ignoredNames = parseItemNames(updated);
		}
		else if ("valuableItems".equals(key))
		{
			cachedValuableList = updated;
			valuableNames = parseItemNames(updated);
		}

		// The settings text area is filled once when the page opens and is not
		// subscribed to config changes. Leaving it stale also writes the old
		// blank text back over this update when the field loses focus.
		syncOpenConfigField(configFieldName(key), updated);
	}

	private String listValue(String key)
	{
		String value = "ignoreList".equals(key) ? config.ignoreList() : config.valuableItems();
		return value == null ? "" : value;
	}

	private static String configFieldName(String key)
	{
		return "ignoreList".equals(key) ? "Ignore list" : "Always show items";
	}

	private static void syncOpenConfigField(String label, String value)
	{
		String shown = value == null ? "" : value;
		for (Window window : Window.getWindows())
		{
			syncOpenConfigField(window, label, shown);
		}
	}

	private static void syncOpenConfigField(Component component, String label, String value)
	{
		if (component instanceof JLabel && label.equals(((JLabel) component).getText()))
		{
			Container parent = component.getParent();
			if (parent != null)
			{
				setConfigText(parent, value);
			}
		}

		if (component instanceof Container)
		{
			for (Component child : ((Container) component).getComponents())
			{
				syncOpenConfigField(child, label, value);
			}
		}
	}

	private static void setConfigText(Container parent, String value)
	{
		for (Component child : parent.getComponents())
		{
			if (child instanceof JTextComponent)
			{
				JTextComponent text = (JTextComponent) child;
				if (!value.equals(text.getText()))
				{
					text.setText(value);
				}
			}
			else if (child instanceof Container)
			{
				setConfigText((Container) child, value);
			}
		}
	}
